function drawSpiral(x, y, size, angle, iterations) {
  if (iterations === 0) return;

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(size, 0);
  ctx.stroke();

  ctx.restore();

  // Recursive call for next iteration
  const newSize = size * 0.8;
  const newAngle = angle + 0.3;
  drawSpiral(x, y, newSize, newAngle, iterations - 1);
}

