// Draw lotus flowers
const drawLotus = (x, y, size) => {
    // Flower center
    ctx.fillStyle = '#FFD700';
    ctx.beginPath();
    ctx.arc(x, y, size * 0.7, 0, Math.PI * 2);
    ctx.fill();

    // Petals
    ctx.fillStyle = '#FFA500';
    for (let i = 0; i < 8; i++) {
        const angle = (i / 8) * Math.PI * 2;
        const startX = x + Math.cos(angle) * (size * 1.5);
        const startY = y + Math.sin(angle) * (size * 1.5);
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(
            startX + Math.cos(angle) * (size * 2),
            startY + Math.sin(angle) * (size * 2)
        );
        ctx.closePath();
        ctx.fill();
    }

    // Stem
    ctx.fillStyle = '#228B22';
    ctx.fillRect(x - 2, y - size * 0.3, 4, size * 0.3);
};

